lumns:1fr 1fr;gap:1rem}.panel{padding:1.25rem}.gate-row,.run-row,.model-row{display:flex;justify-content:space-between;gap:1rem;align-items:center;padding:.85rem 0;border-bottom:1px solid #edf0f3}.run-row,.model-row{flex-wrap:wrap}.run-row>div,.model-row>div{display:grid;gap:.25rem}.plain-copy{color:#64758a;line-height:1.6;font-size:.88rem}.panel ul{padding-left:1.2rem;color:#866b42;font-size:.82rem;line-height:1.6}.funnel{display:grid;gap:.35rem;margin:1rem 0}.funnel span{padding:.55rem .7rem;border-left:3px solid #8eb7ec;background:#f3f7fb;color:#53677f;font-size:.8rem}.status{display:inline-flex;align-items:center;width:max-content;padding:.3rem .55rem;border-radius:999px;font-size:.66rem;font-weight:800;letter-spacing:.05em}.status--good{color:#176849;background:#e3f5ec}.status--warn{color:#8a5e1b;background:#fff1d5}.status--blocked{color:#9a3e49;background:#fde8eb}.status--neutral{color:#5d6d80;background:#edf1f5}.table-wrap{overflow-x:auto;border:1px solid #dce3eb;border-radius:16px;background:#fff}table{width:100%;border-collapse:collapse;text-align:left;font-size:.82rem}th,td{padding:.85rem 1rem;border-bottom:1px solid #edf0f3;vertical-align:top}th{color:#74869b;font-size:.68rem;text-transform:uppercase;letter-spacing:.08em}td strong,td small{display:block;margin-bottom:.25rem}.empty-card{padding:1.4rem;color:#74869b}.reason{flex-basis:100%;color:#9a3e49!important}.prediction-panel{background:#17253d;color:#f3f6fa;border-color:#273b57}.prediction-panel .eyebrow,.prediction-panel .lede{color:#b5c4d4}.prediction-badges{display:flex;flex-wrap:wrap;gap:.5rem}@media(max-width:850px){.hero,.two-col{grid-template-columns:1fr}.metric-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:500px){.metric-grid{grid-template-columns:1fr}.section-heading{align-items:start;flex-direction:column}}
</style>
